'use client';

import React, { useState } from 'react';
import Header from '@/app/component/header';
import { 
  LayoutDashboard, 
  Package, 
  MapPin, 
  Settings, 
  LogOut, 
  Plus, 
  Edit3, 
  Trash2, 
  Lock, 
  Mail, 
  User, 
  ShoppingBag, 
  Clock, 
  Calendar 
} from 'lucide-react';
import './AccountPage.css';

interface Order {
  id: string;
  date: string;
  total: string;
  status: 'Processing' | 'Shipped' | 'Delivered' | 'Cancelled';
  itemsCount: number;
}

export default function AccountPage() {
  // حالة تسجيل الدخول (قم بربطها بنظام Authentication الخاص بك)
  const [isLoggedIn, setIsLoggedIn] = useState<boolean>(false);

  // حقول نموذج تسجيل الدخول
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  const [activeTab, setActiveTab] = useState<'overview' | 'orders' | 'addresses' | 'settings'>('overview');

  const user = {
    name: 'Mohamad Mellal',
    email: 'mohamad@example.com',
    joinedDate: 'January 2026',
  };

  const recentOrders: Order[] = [
    { id: 'ORD-98234', date: 'Sep 10, 2026', total: '$129.00', status: 'Processing', itemsCount: 2 },
    { id: 'ORD-87121', date: 'Aug 28, 2026', total: '$249.50', status: 'Delivered', itemsCount: 1 },
    { id: 'ORD-76510', date: 'Jul 14, 2026', total: '$85.00', status: 'Delivered', itemsCount: 3 },
  ];

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginEmail && loginPassword) {
      setIsLoggedIn(true);
    }
  };

  // 1. عرض صفحة تسجيل الدخول إذا لم يكن المستخدم مسجلاً
  if (!isLoggedIn) {
    return (
      <div>
        <Header />
        <div className="login-page-wrapper">
          <div className="login-card">
            <div className="login-header">
              <h2>Welcome Back</h2>
              <p>Sign in to access your OBSIDIAN-X account</p>
            </div>

            <form onSubmit={handleLoginSubmit} className="login-form">
              <div className="input-field-group">
                <label>Email Address</label>
                <div className="input-with-icon">
                  <Mail className="field-icon" size={18} />
                  <input 
                    type="email" 
                    placeholder="name@example.com" 
                    value={loginEmail}
                    onChange={(e) => setLoginEmail(e.target.value)}
                    required 
                  />
                </div>
              </div>

              <div className="input-field-group">
                <label>Password</label>
                <div className="input-with-icon">
                  <Lock className="field-icon" size={18} />
                  <input 
                    type="password" 
                    placeholder="••••••••" 
                    value={loginPassword}
                    onChange={(e) => setLoginPassword(e.target.value)}
                    required 
                  />
                </div>
              </div>

              <button type="submit" className="login-submit-btn">
                Sign In
              </button>
            </form>

            <div className="login-footer">
              <p>Don't have an account? <a href="#">Create One</a></p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // 2. عرض لوحة التحكم بعد تسجيل الدخول
  return (
    <div>
      <Header />
      <div className="account-page-container">
        <div className="account-layout">
          
          {/* Sidebar Navigation */}
          <aside className="account-sidebar">
            <div className="user-profile-summary">
              <div className="avatar-wrapper">
                <span className="avatar-placeholder">{user.name.charAt(0)}</span>
              </div>
              <h3 className="user-name">{user.name}</h3>
              <p className="user-email">{user.email}</p>
            </div>

            <nav className="account-nav">
              <button 
                className={`nav-item ${activeTab === 'overview' ? 'active' : ''}`}
                onClick={() => setActiveTab('overview')}
              >
                <LayoutDashboard size={18} />
                <span>Dashboard</span>
              </button>
              <button 
                className={`nav-item ${activeTab === 'orders' ? 'active' : ''}`}
                onClick={() => setActiveTab('orders')}
              >
                <Package size={18} />
                <span>My Orders</span>
              </button>
              <button 
                className={`nav-item ${activeTab === 'addresses' ? 'active' : ''}`}
                onClick={() => setActiveTab('addresses')}
              >
                <MapPin size={18} />
                <span>Addresses</span>
              </button>
              <button 
                className={`nav-item ${activeTab === 'settings' ? 'active' : ''}`}
                onClick={() => setActiveTab('settings')}
              >
                <Settings size={18} />
                <span>Account Settings</span>
              </button>
              <button 
                className="nav-item logout-btn"
                onClick={() => setIsLoggedIn(false)}
              >
                <LogOut size={18} />
                <span>Logout</span>
              </button>
            </nav>
          </aside>

          {/* Main Content Area */}
          <main className="account-content">
            
            {activeTab === 'overview' && (
              <div className="tab-content">
                <h2 className="section-title">Dashboard Overview</h2>
                
                <div className="stats-grid">
                  <div className="stat-card">
                    <div className="stat-icon-wrapper">
                      <ShoppingBag size={20} />
                    </div>
                    <div>
                      <h4>Total Orders</h4>
                      <p className="stat-value">{recentOrders.length}</p>
                    </div>
                  </div>
                  <div className="stat-card">
                    <div className="stat-icon-wrapper">
                      <Clock size={20} />
                    </div>
                    <div>
                      <h4>Active Orders</h4>
                      <p className="stat-value">1</p>
                    </div>
                  </div>
                  <div className="stat-card">
                    <div className="stat-icon-wrapper">
                      <Calendar size={20} />
                    </div>
                    <div>
                      <h4>Member Since</h4>
                      <p className="stat-value">{user.joinedDate}</p>
                    </div>
                  </div>
                </div>

                <div className="recent-orders-section">
                  <div className="section-header">
                    <h3>Recent Orders</h3>
                    <button onClick={() => setActiveTab('orders')} className="link-btn">View All</button>
                  </div>
                  
                  <div className="orders-table-wrapper">
                    <table className="orders-table">
                      <thead>
                        <tr>
                          <th>Order ID</th>
                          <th>Date</th>
                          <th>Items</th>
                          <th>Total</th>
                          <th>Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {recentOrders.map((order) => (
                          <tr key={order.id}>
                            <td className="order-id">{order.id}</td>
                            <td>{order.date}</td>
                            <td>{order.itemsCount} items</td>
                            <td>{order.total}</td>
                            <td>
                              <span className={`status-badge ${order.status.toLowerCase()}`}>
                                {order.status}
                              </span>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'orders' && (
              <div className="tab-content">
                <h2 className="section-title">My Orders</h2>
                <div className="orders-table-wrapper">
                  <table className="orders-table">
                    <thead>
                      <tr>
                        <th>Order ID</th>
                        <th>Date</th>
                        <th>Items</th>
                        <th>Total</th>
                        <th>Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {recentOrders.map((order) => (
                        <tr key={order.id}>
                          <td className="order-id">{order.id}</td>
                          <td>{order.date}</td>
                          <td>{order.itemsCount} items</td>
                          <td>{order.total}</td>
                          <td>
                            <span className={`status-badge ${order.status.toLowerCase()}`}>
                              {order.status}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {activeTab === 'addresses' && (
              <div className="tab-content">
                <div className="section-header">
                  <h2 className="section-title">Saved Addresses</h2>
                  <button className="primary-action-btn">
                    <Plus size={16} /> Add New Address
                  </button>
                </div>
                
                <div className="addresses-grid">
                  <div className="address-card default">
                    <span className="default-tag">Default</span>
                    <h4>Mohamad Mellal</h4>
                    <p>123 Tech Street, Suite 400</p>
                    <p>Algiers, Algeria</p>
                    <p>Phone: +213 550 000 000</p>
                    <div className="card-actions">
                      <button className="action-link"><Edit3 size={14} /> Edit</button>
                      <button className="action-link danger"><Trash2 size={14} /> Delete</button>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'settings' && (
              <div className="tab-content">
                <h2 className="section-title">Account Settings</h2>
                <form className="settings-form" onSubmit={(e) => e.preventDefault()}>
                  <div className="form-group">
                    <label>Full Name</label>
                    <div className="input-with-icon">
                      <User size={18} className="field-icon" />
                      <input type="text" defaultValue={user.name} />
                    </div>
                  </div>
                  <div className="form-group">
                    <label>Email Address</label>
                    <div className="input-with-icon">
                      <Mail size={18} className="field-icon" />
                      <input type="email" defaultValue={user.email} />
                    </div>
                  </div>
                  <div className="form-group">
                    <label>New Password</label>
                    <div className="input-with-icon">
                      <Lock size={18} className="field-icon" />
                      <input type="password" placeholder="Leave blank to keep current password" />
                    </div>
                  </div>
                  <button type="submit" className="primary-action-btn">Save Changes</button>
                </form>
              </div>
            )}

          </main>

        </div>
      </div>
    </div>
  );
}